import {
  WhatsAppOutlined,
  UploadOutlined,
  PaperClipOutlined,
  DeleteOutlined,
  UserOutlined,
  PhoneOutlined,
  IdcardOutlined,
  MailOutlined,
  EnvironmentOutlined,
  FileTextOutlined,
} from '@ant-design/icons';
import { createCrudApi, fileApi } from '../api/client';
import api from '../api/client';
import { PageHeader } from '../components/PageHeader';

interface Customer {
  id: string;
  name: string;
  address?: string;
  phone: string;
  identityNumber?: string;
  whatsappNumber?: string;
  email?: string;
  notes?: string;
}

interface FormValues {
  name: string;
  address?: string;
  phone: string;
  identityNumber?: string;
  whatsappNumber?: string;
  email?: string;
  notes?: string;
}

const customersApi = createCrudApi<Customer>('customers');

export default function Customers() {
  const [form] = Form.useForm<FormValues>();
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Customer | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [selectedRowKeys, setSelectedRowKeys] = useState<any[]>([]);
  const [fileList, setFileList] = useState<UploadFile[]>([]);

  const fetchCustomers = async () => {
    setLoading(true);
    try {
      const { data } = await customersApi.getAll();
      setCustomers(Array.isArray(data) ? data : (data?.data || []));
    } catch (error) {
      console.error(error);
      message.error('تعذر تحميل قائمة العملاء');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCustomers();
  }, []);

  const filtered = customers.filter((c) => {
    const q = search.trim().toLowerCase();
    if (!q) return true;
    return (
      (c.name || '').toLowerCase().includes(q) ||
      (c.phone || '').toLowerCase().includes(q)
    );
  });

  const openAdd = () => {
    setEditing(null);
    form.resetFields();
    setFileList([]);
    setModalOpen(true);
  };

  const openEdit = () => {
    if (selectedRowKeys.length === 0) {
      message.warning('يرجى اختيار عميل للتعديل');
      return;
    }
    const selected = customers.find((c) => (c as any)._id === selectedRowKeys[0]);
    if (!selected) return;
    setEditing(selected);
    form.setFieldsValue(selected);
    setFileList([]);
    setModalOpen(true);
  };

  const handleSubmit = async () => {
    let values: FormValues;
    try {
      values = await form.validateFields();
    } catch {
      return;
    }

    setSubmitting(true);
    try {
      let customerId: string;

      if (editing) {
        await customersApi.update((editing as any)._id, values);
        customerId = (editing as any)._id;
        message.success('تم تحديث بيانات العميل');
      } else {
        const res = await customersApi.create(values);
        customerId = res.data?.data?._id || res.data?.data?.id || res.data?._id || res.data?.id;
        message.success('تم إضافة العميل بنجاح');
      }

      // رفع المرفقات إن وجدت
      if (fileList.length > 0) {
        for (const file of fileList) {
